import React, { Component } from "react";
import NavBar from "./components/navbar/NavBar";
import GlobalStyles from "./styles/Global";
import Slideshow from './components/slideshow/SlideShow';
import Info from './components/Info';
import About from './components/About';
import Services from './components/Services';
import References from './components/References';

class App extends Component {

  state = {
    showInfoComponent: false,
    showAboutComponent: false,
    showServicesComponent: false,
  }

  showInfoComponentHandler = () => {
    this.setState({ ...this.state, showInfoComponent: true, showAboutComponent: false, showServicesComponent: false })
  }

  showAboutComponentHandler = () => {
    this.setState({ ...this.state, showInfoComponent: false, showAboutComponent: true, showServicesComponent: false })
  }

  showServicesComponentHandler = () => {
    this.setState({ ...this.state, showInfoComponent: false, showAboutComponent: false, showServicesComponent: true })
  }

  render() {

    const {
      showInfoComponent,
      showAboutComponent,
      showServicesComponent
    } = this.state

    const info = showInfoComponent && <Info />
    const about = showAboutComponent && <About />
    const services = showServicesComponent && <Services />
    const navbar = (<NavBar showInfoComponentHandler={this.showInfoComponentHandler}
      showAboutComponentHandler={this.showAboutComponentHandler}
      showServicesComponentHandler={this.showServicesComponentHandler}
    />)

    return (
      <>
        <NavBar />
        <Slideshow />
        <Info />
        <About />
        <Services />
        <References />
        <GlobalStyles />
      </>
    );
  }
}

export default App;
